  // comparación de cambios (server/compare.ts)
  'tool.compare.description': { es: 'work-shelter (el juego desde el que te manejan): genera la página de comparación de tus cambios (la rama frente a su base, con lo que aún no está en un commit) para que el Supervisor los revise antes de subirlos. Enlaza la ruta que devuelve en tu respuesta, como enlace Markdown: el Supervisor la abre en el juego, deja notas en las líneas y te llegan aquí. Úsala antes de cada push, o cuando te pida ver los cambios.', en: 'work-shelter (the game you are being driven from): generates the compare page of your changes (the branch against its base, including what is not committed yet) so the Overseer can review them before they are pushed. Link the path it returns in your reply, as a Markdown link: the Overseer opens it in the game, leaves notes on the lines and they reach you here. Use it before every push, or when asked to show the changes.' },
  'tool.compare.paramBase': { es: 'Rama o commit con el que comparar; si no, la rama remota que sigue o la principal', en: 'Branch or commit to compare against; otherwise, the remote branch it tracks or the main one' },
  'tool.compare.paramHead': { es: 'Rama o commit que comparar, del mismo repo (por defecto, HEAD): así se compara una rama desde la copia principal sin abrirle un worktree. Con otro que HEAD, sin lo que no está en un commit', en: 'Branch or commit to compare, of the same repo (HEAD by default): this compares a branch from the main copy without opening a worktree for it. With one other than HEAD, without what is not committed' },
  'tool.compare.uncommittedOtherHead': { es: 'Lo que no está en un commit solo se compara con HEAD, no con «{head}»: quita uncommitted o head.', en: 'Uncommitted changes can only be compared with HEAD, not with “{head}”: drop uncommitted or head.' },
  'tool.compare.noSuchHead': { es: 'No existe «{head}» en este repo (head: una rama o un commit).', en: '“{head}” does not exist in this repo (head: a branch or a commit).' },
  'tool.compare.paramUncommitted': { es: 'Incluir lo que aún no está en un commit (por defecto, sí)', en: 'Include what is not committed yet (yes by default)' },
  'tool.compare.ready': { es: 'Página lista: {enlace} — {rama} frente a {base}: {n} archivos, +{mas} −{menos}. Enlázala así en tu respuesta para que el Supervisor la abra en el juego.', en: 'Page ready: {enlace} — {rama} against {base}: {n} files, +{mas} −{menos}. Link it like this in your reply so the Overseer can open it in the game.' },
  'tool.compare.failed': { es: 'No se pudo generar: {error}', en: 'Could not generate it: {error}' },
  'tool.compare.paramFolder': { es: 'Otro worktree del mismo repo que comparar (ruta absoluta); si no, la carpeta de esta conversación', en: 'Another worktree of the same repo to compare (absolute path); otherwise, this conversation\'s folder' },
  'tool.compare.notAWorktree': { es: '«{carpeta}» no es un worktree de este repo (git worktree list).', en: '“{carpeta}” is not a worktree of this repo (git worktree list).' },
  'tool.compare.noSuchBase': { es: 'No existe «{base}» en este repo.', en: '“{base}” does not exist in this repo.' },
