  'tool.compare.noChanges': { es: 'Sin cambios frente a la base.', en: 'No changes against the base.' },
  'tool.preflight.estadoDescription': { es: 'work-shelter: el pre-flight de tu parte de la tarea (la de tu worktree): compare validado en tu commit, la lista «antes de subir» del Supervisor con lo contestado, sincronía, CI, revisión (hilos sin resolver) y bloqueos. Míralo antes de pedir subir.', en: 'work-shelter: the pre-flight of your part of the task (your worktree\'s): compare validated at your commit, the Overseer\'s “before pushing” list with what is answered, sync, CI, review (unresolved threads) and blockers. Check it before asking to push.' },
  'tool.preflight.responderDescription': { es: 'work-shelter: contesta un punto de la lista «antes de subir» del Supervisor para tu commit actual (un commit nuevo pide contestarla otra vez). item: su número o su texto; status: ok, n/a (con una nota que diga por qué) o pending; note: lo que has comprobado y cómo.', en: 'work-shelter: answer one item of the Overseer\'s “before pushing” list for your current commit (a new commit needs it answered again). item: its number or text; status: ok, n/a (with a note saying why) or pending; note: what you checked and how.' },
  'tool.preflight.heading': { es: 'Pre-flight de {clave} · {sala} · {rama} @ {head}', en: 'Pre-flight of {clave} · {sala} · {rama} @ {head}' },
  'tool.preflight.items': { es: 'Antes de subir (para este commit; los tuyos y los que pone el repo: «npm run x», «make x» o «pre-commit» se ejecutan; «skill · x», usa esa skill; «CLAUDE.md · x», lo que dice el repo):', en: 'Before pushing (for this commit; the Overseer\'s and the repo\'s: run «npm run x», «make x» or «pre-commit»; for «skill · x», use that skill; «CLAUDE.md · x» is what the repo asks):' },
