  'tool.preflight.noTask': { es: 'Esta carpeta no es el worktree de una tarea (sin clave en su nombre ni en su rama): no hay pre-flight.', en: 'This folder is not a task worktree (no key in its name or branch): there is no pre-flight.' },
  'tool.preflight.noSuchItem': { es: '«{item}» no está en la lista: {lista}', en: '“{item}” is not in the list: {lista}' },
