  'tool.decor.check.tooLong': { es: '{que}: «{t}» tiene {n} letras y caben {max}; queda «{corto}». Acórtalo o pártelo en dos líneas.', en: '{que}: «{t}» has {n} letters and {max} fit; it stays «{corto}». Shorten it or split it into two lines.' },
