  'tool.decor.check.coversBoard': { es: '{que} tapa el tablero de tareas de la sala: el juego no lo pone. Llévalo a otro sitio.', en: '{que} covers the room\'s task board: the game leaves it out. Move it elsewhere.' },
  'tool.decor.check.inWorkZone': { es: '{que} está en la zona de trabajo (el tercio del centro, con la mesa del habitante y el tablero de tareas): el juego no lo pone. Llévalo a un lado.', en: '{que} is in the work zone (the middle third, with the dweller\'s desk and the task board): the game leaves it out. Move it to one side.' },
  'tool.decor.check.onPanel': { es: '{que} está encima del panel de la sala (el terminal junto a la entrada): el juego no lo pone. Llévalo a otro sitio.', en: '{que} is on top of the room panel (the terminal by the entrance): the game leaves it out. Move it elsewhere.' },
  'tool.decor.check.workZoneFixed': { es: 'La mesa del habitante y el tablero de tareas tienen su sitio fijo en el centro: no hace falta dar pantallaRepo ni la x/z del puesto (lo ignoro).', en: 'The dweller\'s desk and the task board have a fixed spot in the middle: there is no need for pantallaRepo or the desk\'s x/z (ignored).' },
  'tool.decor.yourPanel': { es: 'Zona de trabajo: el tercio del centro (|x| < {zona}, detrás del pasillo) es la mesa del habitante con el tablero de tareas encima; no pongas piezas ahí. Panel de la sala: un terminal en el suelo en x = {x}, z = {z} ({ancho} × {fondo} m), junto a la entrada; déjalo libre. Los dos tercios de los lados son tuyos.', en: 'Work zone: the middle third (|x| < {zona}, behind the walkway) is the dweller\'s desk with the task board above it; put no pieces there. Room panel: a floor terminal at x = {x}, z = {z} ({ancho} × {fondo} m), by the entrance; leave it clear. The two side thirds are yours.' },
  'tool.decor.yourBoard': { es: 'Tablero de tareas de tu sala (no lo tapes con piezas junto a la pared ni con carteles): centrado en x = {x}, y = {y}, de {ancho} × {alto} m en la pared del fondo.', en: 'Your room\'s task board (do not cover it with pieces near the wall or with signs): centred at x = {x}, y = {y}, {ancho} × {alto} m on the back wall.' },
