  'tool.decor.check.outLeft': { es: 'pieces[{i}] ({modelo}) se sale por la izquierda de la sala (ocupa de x={x0} a {x1}).', en: 'pieces[{i}] ({modelo}) sticks out on the left of the room (it takes x={x0} to {x1}).' },
  'tool.decor.check.outRight': { es: 'pieces[{i}] ({modelo}) se sale por la derecha de la sala (ocupa de x={x0} a {x1}).', en: 'pieces[{i}] ({modelo}) sticks out on the right of the room (it takes x={x0} to {x1}).' },
  'tool.decor.check.intoBackWall': { es: 'pieces[{i}] ({modelo}) se mete en la pared del fondo (z mínima {z}): usa «wall: true» o acércala.', en: 'pieces[{i}] ({modelo}) goes into the back wall (minimum z {z}): use «wall: true» or bring it closer.' },
  'tool.decor.check.throughCeiling': { es: 'pieces[{i}] ({modelo}) atraviesa el techo (llega a y={y}).', en: 'pieces[{i}] ({modelo}) goes through the ceiling (reaches y={y}).' },
  'tool.decor.check.intoAisle': { es: 'pieces[{i}] ({modelo}) invade el pasillo (llega a z={z}; deja libre z > {pasillo}).', en: 'pieces[{i}] ({modelo}) gets into the aisle (reaches z={z}; keep z > {pasillo} free).' },
  'tool.decor.check.floats': { es: 'pieces[{i}] ({modelo}) flota a y={y}: sin «wall: true» ni «restsOn», queda en el aire (bien para algo que cuelga del techo).', en: 'pieces[{i}] ({modelo}) floats at y={y}: without «wall: true» or «restsOn» it hangs in the air (fine for something hanging from the ceiling).' },
  'tool.decor.check.overlapFloor': { es: 'pieces[{a}] ({ma}) y pieces[{b}] ({mb}) se atraviesan en el suelo ({dx} × {dz} m): sepáralas o pon una «restsOn» la otra.', en: 'pieces[{a}] ({ma}) and pieces[{b}] ({mb}) overlap on the floor ({dx} × {dz} m): move them apart or put one «restsOn» the other.' },
